TEST(MacroFunctions, SBUInt8InRange) {
    ternary([](auto v, auto s, auto e) {
        static_assert(std::is_same_v<decltype(SBUInt8InRange(v, s, e)), decltype((m::SBUInt8InRange)(v, s, e))>);
        EXPECT_EQ(SBUInt8InRange(v, s, e), (m::SBUInt8InRange)(v, s, e));
    });
}
